const labels = ['iso-2022-jp','csiso2022jp',' \tISO-2022-JP\r\n'];
for (const label of labels) console.log(new TextDecoder(label).encoding);
let failures=0;
for (const label of ['iso2022jp','iso-2022-jp-2','\u00a0iso-2022-jp']) {
 try {new TextDecoder(label);} catch(e) {if (e instanceof RangeError) failures++;}
}
console.log(failures);

const b=Uint8Array.from([65,27,40,74,92,126,27,40,73,33,95,27,36,66,70,124,75,92,27,40,66,90]);
for(const fatal of [false,true]) console.log(new TextDecoder('iso-2022-jp',{fatal}).decode(b));
console.log(new TextDecoder('iso-2022-jp').decode(Uint8Array.from([27,36,64,36,34])));

const input=Uint8Array.from([65,27,40,74,92,126,27,40,73,33,95,27,36,66,70,124,75,92,27,40,66,90]);
for(let cut=0;cut<=input.length;cut++) {
 const d=new TextDecoder('iso-2022-jp');
 let text=d.decode(input.subarray(0,cut),{stream:true});
 if(d.decode(new Uint8Array(0),{stream:true})!=='')throw new Error('early EOF');
 text+=d.decode(input.subarray(cut),{stream:true})+d.decode();
 if(text!=='A¥‾｡ﾟ日本Z')throw new Error('split '+cut);
}
const d=new TextDecoder('iso-2022-jp');let text='';
for(const byte of input)text+=d.decode(Uint8Array.of(byte),{stream:true});
text+=d.decode();if(text!=='A¥‾｡ﾟ日本Z')throw new Error('bytewise');
console.log('ISO_SPLITS_OK');

const constructors=[Int8Array,Uint8Array,Uint8ClampedArray,Int16Array,Uint16Array,Int32Array,Uint32Array,Float32Array,Float64Array,BigInt64Array,BigUint64Array,DataView];
for(const C of constructors){
 const bytes=new Uint8Array(32);bytes.fill(65);bytes[8]=27;bytes[9]=40;bytes[10]=74;bytes[11]=92;bytes[12]=126;
 const view=C===DataView?new DataView(bytes.buffer,8,8):new C(bytes.buffer,8,8/C.BYTES_PER_ELEMENT);
 const value=new TextDecoder('iso-2022-jp').decode(view);
 if(value!=='¥‾AAA')throw new Error(C.name+': '+value);
}
console.log('ISO_VIEWS_OK');

const d=new TextDecoder('iso-2022-jp');
const bytes=Uint8Array.from([0,27,36,66,36,0]);
console.log(JSON.stringify(d.decode(new DataView(bytes.buffer,1,4),{stream:true})));
bytes.fill(0);console.log(d.decode(Uint8Array.of(34)));
console.log(d.decode(Uint8Array.of(92)));

const d=new TextDecoder('iso-2022-jp');const bytes=Uint8Array.of(92);
const output=d.decode(bytes,{get stream(){d.decode(Uint8Array.from([27,40,74]),{stream:true});return false;}});
console.log(output);console.log(d.decode(bytes));

const d=new TextDecoder('iso-2022-jp');
console.log(JSON.stringify(d.decode(Uint8Array.from([27,40,66]),{stream:true})));
console.log(JSON.stringify(d.decode(new Uint8Array(0),{stream:true})));
console.log(d.decode(Uint8Array.from([27,40,74,92])));
console.log(new TextDecoder('iso-2022-jp').decode(Uint8Array.from([27,40,74,92,27,40,66,27,40,74,92])));

let failed=0;
for(const bytes of [[14],[255],[27],[27,36],[27,36,66,36],[27,40,66,27,40,74]]){
 try{new TextDecoder('iso-2022-jp',{fatal:true}).decode(Uint8Array.from(bytes));}
 catch(e){if(e instanceof TypeError)failed++;else throw e;}
}
console.log(failed);
const d=new TextDecoder('iso-2022-jp',{fatal:true});d.decode(Uint8Array.from([27]),{stream:true});
try{d.decode();}catch(e){console.log(e instanceof TypeError);}
console.log(d.decode(Uint8Array.of(65)));

for(const ignoreBOM of [false,true]){
 console.log(new TextDecoder('iso-2022-jp',{ignoreBOM}).decode(Uint8Array.from([239,187,191])));
 console.log(JSON.stringify(new TextDecoder('iso-2022-jp',{ignoreBOM}).decode(Uint8Array.from([0,10,13,127]))));
}
console.log(new TextDecoder('iso-2022-jp').decode(Uint8Array.from([14,15,128])));
